Calibrating a DHT22 temperature and humidity sensor involves adjusting its readings to match the actual environmental conditions. Since the DHT22 sensor is a relative humidity sensor, it can be calibrated using a simple equation. Here's the code in Arduino to calibrate the DHT22 sensor:

```cpp
#include <DHT.h>

#define DHTPIN 2  // Digital pin connected to the DHT sensor output
#define DHTTYPE DHT22   // DHT 22  (AM2302), DHT 21, ...

DHT dht(DHTPIN, DHTTYPE);

const int numReadings = 10;  // Number of readings to take for calibration
int readings[numReadings];      // Array to hold readings
int index = 0;                // Index of the current reading

void setup() {
  Serial.begin(9600);  // Initialize serial communication
  dht.begin();
}

void loop() {
  int sensorValue = dht.readHumidity();
  if (sensorValue == DHTLIB_OK && !isnan(sensorValue)) {
    readings[index] = sensorValue;
    index = (index + 1) % numReadings;
    if (index == 0) {
      Serial.print("Before calibration: "); // Print the values before calibration
      Serial.print("Min: ");
      Serial.print(min(readings, numReadings));
      Serial.print(" Max: ");
      Serial.println(max(readings, numReadings));
    }
  }
}

int max(int arr[], int n) {
  int mx = arr[0];
  for (int i = 1; i < n; i++)
    if (arr[i] > mx)
      mx = arr[i];
  return mx;
}

int min(int arr[], int n) {
  int mn = arr[0];
  for (int i = 1; i < n; i++)
    if (arr[i] < mn)
      mn = arr[i];
  return mn;
}
```
