import { FeedbackContext } from './FeedbackContext';

const FeedbackForm = () => {
  const { feedback, handleFeedback } = useContext(FeedbackContext);

  return (
    <form>
      {Object.keys(feedback).map((question, index) => (
        <div key={index}>
          <label>{question}</label>
          <input
            type="text"
            name={question}
            value={feedback[question]}
            onChange={handleFeedback}
          />
        </div>
