Here is a basic implementation of a pendulum simulation in JavaScript and HTML5 canvas. The pendulum starts at a specified initial angle and releases when the user clicks the "Release" button.

Please note that this is a simplified simulation and doesn't take into account many factors that could affect the motion of a real pendulum, such as air resistance or friction in the pivot.

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Pendulum Simulation</title>
  <style>
    #canvas {
      border: 1px solid black;
    }
  </style>
</head>
<body>
  <canvas id="canvas" width="600" height="600"></canvas>
  <label>Initial Angle (degrees): <input type="number" id="initial-angle" value="45"></label>
  <button id="release-button">Release</button>
  <script>
    let canvas = document.getElementById('canvas');
    let ctx = canvas.getContext('2d');
    let width = canvas.width;
    let height = canvas.height;
    let initialAngle = 45 * Math.PI / 180; // convert degrees to radians
    let gravity = 9.81; // m/s^2
    let mass = 1; // kg
    let length = 100; // m
    let releaseAngle = 0;
    let angle = initialAngle;
    let velocity = 0;
    let dt = 0.01; // seconds
    let isReleased = false;

    function update() {
      if (!isReleased) return;
      velocity += (-gravity * Math.sin(angle)) / length;
      angle += velocity * dt;
      releaseAngle = angle;
      if (Math.abs(angle) > Math.PI / 2) {
        isReleased = false;
        angle = releaseAngle;
      }
    }

    function draw() {
      ctx.clearRect(0, 0, width, height);
      ctx.translate(width / 2, height / 2);
      ctx.rotate(angle);
      ctx.beginPath();
      ctx.moveTo(0, -length);
      ctx.lineTo(0, -length);
      ctx.stroke();
      ctx.fillStyle = 'blue';
      ctx.fillRect(-1, -length - 10, 2, 20);
      requestAnimationFrame(() => {
        update();
        draw();
      });
