```go
package main

import (
    "context"
    "log"

    "github.com/aws/aws-lambda-go/lambda"
    "github.com/aws/aws-sdk-go/aws"
    "github.com/aws/aws-sdk-go/aws/session"
    "github.com/aws/aws-sdk-go/service/ec2"
)

func handler(ctx context.Context) (interface{}, error) {
    sess, err := session.NewSession(&aws.Config{Region: aws.String("your-region")}, nil)
    if err != nil {
        log.Println(err)
        return nil, err
    }

    ec2Svc := ec2.New(sess)

    // Get all EBS Snapshots with the specified tag
    resp, err := ec2Svc.DescribeSnapshots(&ec2.DescribeSnapshotsInput{
        Filter: []*ec2.Filter{
            {
                Name:   aws.String("tag:backup-type"),
                Values: []*string{"monthly", "daily", "weekly", "yearly"},
            },
        },
    })
    if err != nil {
        log.Println(err)
        return nil, err
    }

    // Process snapshots
    monthlySnapshots := make([]*ec2.Snapshot, 0)
    dailySnapshots := make([]*ec2.Snapshot, 0)
    weeklySnapshots := make([]*ec2.Snapshot, 0)
    yearlySnapshots := make([]*ec2.Snapshot, 0)

    for _, snapshot := range resp.Snapshots {
        switch *snapshot.Tags[0].Value {
        case "monthly":
            monthlySnapshots = append(monthlySnapshots, snapshot)
        case "daily":
            dailySnapshots = append(dailySnapshots, snapshot)
        case "weekly":
            weeklySnapshots = append(weeklySnapshots, snapshot)
        case "yearly":
            yearlySnapshots = append(yearlySnapshots, snapshot)
        }
    }

    // Delete excess snapshots
    if len(monthlySnapshots) > 14 {
        for i := 0; i < len(monthlySnapshots)-14; i++ {
            err = ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: &monthlySnapshots[i].SnapshotId})
            if err != nil {
                log.Println(err)
                return nil, err
            }
        }
    }

    if len(dailySnapshots) > 10 {
        for i := 0; i < len(dailySnapshots)-10; i++ {
            err = ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: &dailySnapshots[i].SnapshotId})
            if err != nil {
                log.Println(err)
                return nil, err
            }
        }
    }

    if len(weeklySnapshots) > 4 {
        for i := 0; i < len(weeklySnapshots)-4; i++ {
            err = ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: &weeklySnapshots[i].SnapshotId})
            if err != nil {
                log.Println(err)
                return nil, err
            }
        }
    }

    if len(yearlySnapshots) > 1 {
        for i := 1; i < len(yearlySnapshots); i++ {
            err = ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: &yearlySnapshots[i].SnapshotId})
            if err != nil {
                log.Println(err)
                return nil, err
            }
        }
    }

    log.Println("Completed")
    return nil, nil
}

func main() {
    lambda.Start(handler)
}
```
